    $scope.IsLatestROS = false;
    $scope.GetPrevROSData = function (val) {
        if (val === 1 || val === 2 || val === 3) {
            $scope.IsLatestROS = true;
        } else {
            $scope.IsLatestROS = false;
        }
        eHnoteSurgeryService.GetPrevROSData($scope.cacheStorageItem.PatientID, $scope.IsLatestROS).then(function (response) {
            console.log(response);
            if (response.data.rows.length > 0) {
                if (val === 1) {

                    angular.forEach(response.data.rows[0].SystemicHistory, function (item) {
                        item.PatientDetailId = 0;
                    });

                    let tempSystemicArray = [];
                    tempSystemicArray = angular.copy($scope.PreOpObj.SystemicHistory);
                    if (tempSystemicArray.length > 0) {
                        if (response.data.rows[0].SystemicHistory.length > 0) {
                            angular.forEach(response.data.rows[0].SystemicHistory, function (item) {
                                angular.forEach(tempSystemicArray, function (kitem) {
                                    if (kitem.HistoryId !== item.HistoryId) {
                                        let tempArray = $filter('filter')($scope.PreOpObj.SystemicHistory, { 'HistoryId': item.HistoryId }, true);
                                        if (tempArray.length == 0) {
                                            $scope.PreOpObj.SystemicHistory.push(item);
                                        }
                                    } else if (kitem.HistoryId == item.HistoryId) {
                                        let index = $scope.PreOpObj.SystemicHistory.findIndex((x) => x.HistoryId == kitem.HistoryId);
                                        if (index > -1) {
                                            $scope.PreOpObj.SystemicHistory[index].ActiveInd = true;
                                            $scope.PreOpObj.SystemicHistory[index].DeleteInd = "N";
                                        }
                                    }
                                });
                            });
                        }
                    } else {
                        $scope.PreOpObj.SystemicHistory = angular.copy(response.data.rows[0].SystemicHistory);
                    }
                }
                if (val === 2) {

                    angular.forEach(response.data.rows[0].SurgicalHistory, function (item) {
                        item.PatientDetailId = 0;
                    });

                    let tempSurgicalArray = [];
                    tempSurgicalArray = angular.copy($scope.PreOpObj.SurgicalHistory);
                    if (tempSurgicalArray.length > 0) {
                        if (response.data.rows[0].SurgicalHistory.length > 0) {
                            angular.forEach(response.data.rows[0].SurgicalHistory, function (item) {
                                angular.forEach(tempSurgicalArray, function (kitem) {
                                    if (kitem.HistoryId !== item.HistoryId) {
                                        let tempArray = $filter('filter')($scope.PreOpObj.SurgicalHistory, { 'HistoryId': item.HistoryId }, true);
                                        if (tempArray.length == 0) {
                                            $scope.PreOpObj.SurgicalHistory.push(item);
                                        }

                                    } else if (kitem.HistoryId == item.HistoryId) {
                                        let index = $scope.PreOpObj.SurgicalHistory.findIndex((x) => x.HistoryId == kitem.HistoryId);
                                        if (index > -1) {
                                            $scope.PreOpObj.SurgicalHistory[index].ActiveInd = true;
                                            $scope.PreOpObj.SurgicalHistory[index].DeleteInd = "N";
                                        }
                                    }
                                });
                            });
                        }
                    } else {
                        $scope.PreOpObj.SurgicalHistory = angular.copy(response.data.rows[0].SurgicalHistory);
                    }
                }
                if (val === 3) {

                    angular.forEach(response.data.rows[0].Allergy, function (item) {
                        item.PatientDetailId = 0;
                    });

                    let tempAllergyArray = [];
                    tempAllergyArray = angular.copy($scope.PreOpObj.AllergyItems);
                    if (tempAllergyArray.length > 0) {
                        if (response.data.rows[0].Allergy.length > 0) {
                            angular.forEach(response.data.rows[0].Allergy, function (item) {
                                angular.forEach(tempAllergyArray, function (kitem) {
                                    if (kitem.AllergyId !== item.AllergyId) {
                                        let tempArray = $filter('filter')($scope.PreOpObj.AllergyItems, { 'AllergyId': item.AllergyId }, true);
                                        if (tempArray.length == 0) {
                                            $scope.PreOpObj.AllergyItems.push(item);
                                        }

                                    } else if (kitem.AllergyId == item.AllergyId) {
                                        let index = $scope.PreOpObj.AllergyItems.findIndex((x) => x.AllergyId == kitem.AllergyId);
                                        if (index > -1) {
                                            $scope.PreOpObj.AllergyItems[index].ActiveInd = true;
                                            $scope.PreOpObj.AllergyItems[index].DeleteInd = "N";
                                        }
                                    }
                                });
                            });
                        }
                    } else {
                        $scope.PreOpObj.AllergyItems = angular.copy(response.data.rows[0].Allergy);
                    }

                }
            }
            if (!$scope.IsLatestROS) {
                var modalInstance = $uibModal.open({
                    templateUrl: "ASCROSHistory.html",
                    "size": "lg",
                    "resolve": {
                        "SystemicHistory": function () { return response.data.rows[0].SystemicHistory; },
                        "SurgicalHistory": function () { return response.data.rows[0].SurgicalHistory; },
                        "AllergyItems": function () { return response.data.rows[0].Allergy; },
                        "val": function () { return val; },
                        "SystemicHistory1": function () { return $scope.PreOpObj.SystemicHistory; },
                        "SurgicalHistory1": function () { return $scope.PreOpObj.SurgicalHistory; },
                        "AllergyItems1": function () { return $scope.PreOpObj.AllergyItems; },
                    },
                    "controller": function ($scope, $uibModal, $uibModalInstance, SystemicHistory, SurgicalHistory, AllergyItems, val, SystemicHistory1, SurgicalHistory1, AllergyItems1) {
                        $scope.PreOpObj = {
                            "SystemicHistory": [],
                            "SurgicalHistory": [],
                            "AllergyItems": [],
                            "Type": '',
                            "IsSystemicHistory": false,
                            "IsAllergyItems": true,
                            "IsSurgicalHistory": false
                        }

                        $scope.SystemicHistory = SystemicHistory;
                        $scope.SurgicalHistory = SurgicalHistory;
                        $scope.AllergyItems = AllergyItems;

                        if (val === 'Systemic') {
                            $scope.PreOpObj.SystemicHistory = SystemicHistory;
                            $scope.PreOpObj.Type = val;
                        }
                        if (val === 'Surgical') {
                            $scope.PreOpObj.SurgicalHistory = SurgicalHistory;
                            $scope.PreOpObj.Type = val;
                        }
                        if (val === 'Allergies') {
                            $scope.PreOpObj.AllergyItems = AllergyItems;
                            $scope.PreOpObj.Type = val;
                        }

                        $scope.close = function (item) {
                            $uibModalInstance.dismiss("cancel");
                        };

                        $scope.Obj = {
                            "SystemicHistory": [],
                            "SurgicalHistory": [],
                            "AllergyItems": [],
                        }
                        $scope.Obj.SystemicHistory = SystemicHistory1;
                        $scope.Obj.SurgicalHistory = SurgicalHistory1;
                        $scope.Obj.AllergyItems = AllergyItems1;

                        $scope.CopyPreviousAllergy = function (pAllergy) {
                            if (pAllergy != undefined) {
                                var obj = {
                                    "PatientDetailId": 0,
                                    "IsShowAllergySnomedAddInd": pAllergy.IsShowAllergySnomedAddInd || false,
                                    "AllergyId": pAllergy.AllergyId || null,
                                    "RcopiaAllergyId": pAllergy.RcopiaAllergyId || null,
                                    "AllergyName": pAllergy.AllergyName || '',
                                    "OrganId": 4,
                                    "SeverityId": pAllergy.SeverityId || 0,
                                    "SNOMEDId": pAllergy.SNOMEDId || null,
                                    "RxNormID": pAllergy.RxNormID || null,
                                    "NDCID": pAllergy.NDCID || null,
                                    "DrugGroupID": pAllergy.DrugGroupID || null,
                                    "SeverityName": pAllergy.SeverityName || "",
                                    "ReactionId": pAllergy.ReactionId || "",
                                    "StatusId": pAllergy.StatusId || "",
                                    "Duration": pAllergy.Duration || "",
                                    "AllergyTypeId": pAllergy.AllergyTypeId || 0,
                                    "IsEdit": true,
                                    "ShowNote": false,
                                    "ShowDateFormat": true,
                                    "ReactionName": pAllergy.ReactionName || "",
                                    "DurationDate": pAllergy.DurationDate || "",
                                    "StatusName": pAllergy.StatusName || "",
                                    "Remarks": pAllergy.Remarks || "",
                                    "SnomedCode": pAllergy.SnomedCode || "",
                                    "DurationType": 'D',
                                    "OnsetType": 'Date',
                                    "DiagnosisObject": 'D',
                                    "DeleteInd": 'N',
                                }
                                var i = 0;
                                if ($scope.Obj.AllergyItems.length > 0) {
                                    angular.forEach($scope.Obj.AllergyItems, function (item) {
                                        if (item.AllergyId === obj.AllergyId && item.DeleteInd == 'N') {
                                            alertify.error('You have already entered this Allergy');
                                            i++;
                                        }
                                    });
                                }
                                if (i === 0) {
                                    $scope.Obj.AllergyItems.push(obj);
                                    pAllergy.iscopied = true;
                                }
                            }
                        }
                        $scope.CopyPreviousSystemHistory = function (ohitem) {
                            var object = {
                                "PatientDetailId": 0,
                                "HistoryId": ohitem.HistoryId || "",
                                "HistoryName": ohitem.HistoryName || "",
                                "IsEdit": ohitem.IsEdit || true,
                                "ActiveInd": true,
                                "DeleteInd": 'N',
                                "Remarks": ohitem.Remarks || "",
                                "SnomedCodeobj": ohitem.SNOMED || "",
                                "OrganId": ohitem.OrganId || "",
                                "Duration": ohitem.Duration || "",
                                "DurationType": ohitem.DurationType || "D",
                                "DurationTypeName": ohitem.DurationTypeName || "Day(s)",
                                "DurationDate": ohitem.DurationDate || "",
                                "ShowNote": false,
                                "SNOMEDId": ohitem.SNOMEDId || null,
                                "SNOMEDCODE": ohitem.SNOMED || "",
                                "ICD10CODE": ohitem.ICD10CODE || "",
                                "DiagnosisObject": ohitem.ICD10CODE || "",
                                "DiagnosisId": ohitem.DiagnosisId || null,
                                "SeverityId": ohitem.SeverityId || null,
                                "StatusId": 1,
                                "SeverityDateTime": ohitem.SeverityDateTime || "",
                                "ShowDateFormat": true,
                            };
                            var i = 0;
                            if ($scope.Obj.SystemicHistory.length > 0) {
                                angular.forEach($scope.Obj.SystemicHistory, function (item) {
                                    if (item.HistoryId === object.HistoryId && item.DeleteInd === 'N') {
                                        alertify.error('You have already entered this Systemic history');
                                        i++;
                                    }
                                });
                            }
                            if (i === 0) {
                                $scope.Obj.SystemicHistory.push(object);
                                ohitem.iscopied = true;
                            }
                        }
                        $scope.CopyPreviousSurgical = function (surgicalHistory) {
                            var object = {
                                "PatientDetailId": 0,
                                "HistoryId": surgicalHistory.HistoryId,
                                "HistoryName": surgicalHistory.HistoryName,
                                "IsEdit": true,
                                "showSurgicalHistory": surgicalHistory.showSurgicalHistory || false,
                                "ActiveInd": true,
                                "DeleteInd": 'N',
                                "DurationDate": surgicalHistory.DurationDate || "",
                                "Duration": surgicalHistory.Duration || "",
                                "DurationType": surgicalHistory.DurationType || "D",
                                "DurationTypeName": surgicalHistory.DurationTypeName || "Day(s)",
                                "Remarks": surgicalHistory.Remarks || "",
                                "ShowDateFormat": surgicalHistory.DurationDate ? true : false,
                                "ShowNote": false,
                                "ModifierId": surgicalHistory.ModifierId || "",
                                "MODIFIERCODE": surgicalHistory.MODIFIERCODE || "",
                                "ModifierObj": surgicalHistory.ModifierObj || "",
                                "CPTCode": surgicalHistory.CPTCode || "",
                                "ProcedureId": surgicalHistory.ProcedureId || "",
                                "CPTObj": surgicalHistory.CPTCode || "",
                                "ShowDateFormat": true
                            };
                            var i = 0;
                            if ($scope.Obj.SurgicalHistory.length > 0) {
                                angular.forEach($scope.Obj.SurgicalHistory, function (item) {
                                    if (item.HistoryId === object.HistoryId && item.DeleteInd === 'N') {
                                        alertify.error('You have already entered this Surgical history');
                                        i++;
                                    }
                                });
                            }
                            if (i === 0) {
                                $scope.Obj.SurgicalHistory.push(object);
                                surgicalHistory.iscopied = true;
                            }

                        }

                        $scope.ChangeROSHistory = function (val) {
                            if (val == 'Systemic') {
                                $scope.PreOpObj.SystemicHistory = $scope.SystemicHistory;
                                $scope.PreOpObj.IsSystemicHistory = true;
                                $scope.PreOpObj.IsAllergyItems = false;
                                $scope.PreOpObj.IsSurgicalHistory = false;
                            }
                            if (val == 'Surgical') {
                                $scope.PreOpObj.SurgicalHistory = $scope.SurgicalHistory;
                                $scope.PreOpObj.IsSystemicHistory = false;
                                $scope.PreOpObj.IsAllergyItems = false;
                                $scope.PreOpObj.IsSurgicalHistory = true;
                            }
                            if (val == 'Allergies') {
                                $scope.PreOpObj.AllergyItems = $scope.AllergyItems;
                                $scope.PreOpObj.IsSystemicHistory = false;
                                $scope.PreOpObj.IsAllergyItems = true;
                                $scope.PreOpObj.IsSurgicalHistory = false;
                            }
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    $scope.PreOpObj.AllergyItems = angular.copy(result.AllergyItems);
                    $scope.PreOpObj.SystemicHistory = angular.copy(result.SystemicHistory);
                    $scope.PreOpObj.SurgicalHistory = angular.copy(result.SurgicalHistory);

                }, function () { });
            }
        }, function (err) {
            alertify.error("Fetching Data failed!");
            console.log(err);
        });
    };

    $scope.ShowROSPopUp = function (item) {
        item = item || 'Allergies';

        $scope.PreOpObj.AllergyItems = $scope.PreOpObj.AllergyItems || [];
        $scope.PreOpObj.SystemicHistory = $scope.PreOpObj.SystemicHistory || [];
        $scope.PreOpObj.SurgicalHistory = $scope.PreOpObj.SurgicalHistory || [];
        $scope.PreOpObj.LifestyleDetail = $scope.PreOpObj.LifestyleDetail || [];
        $scope.PreOpObj.PatientDetails = $scope.PreOpObj.PatientDetails || {};
        $scope.PreOpObj.PatientDetails.S3URL = $scope.cacheStorageItem.PatientImageS3URL || "";
        $scope.PreOpObj.PatientName = $scope.cacheStorageItem.PatientName || "";
        $scope.PreOpObj.PatientDisplayId = $scope.cacheStorageItem.PatientDisplayId || "";
        $scope.PreOpObj.Gender = $scope.cacheStorageItem.Gender || "";
        $scope.PreOpObj.Age = $scope.cacheStorageItem.Age || "";
        $scope.PreOpObj.PatientDOB = $scope.cacheStorageItem.PatientDOB || "";
        $scope.PreOpObj.AppointmentTypeId = $scope.cacheStorageItem.AppointmentTypeId || 0;
        $scope.PreOpObj.PatientVisitId = $scope.cacheStorageItem.PatientVisitId || 0;
        $scope.PreOpObj.PatientID = $scope.cacheStorageItem.PatientID || '';
        $scope.PreOpObj.PatientId = $scope.cacheStorageItem.PatientID || '';
        $scope.PreOpObj.FullName = $scope.cacheStorageItem.PatientName || '';
        $scope.PreOpObj.PatientDetails.DisplayId = $scope.cacheStorageItem.PatientDisplayId || '';

        $scope.PreOpObj.MentalStatus = $scope.PreOpObj.MentalStatus || '';

        $scope.PreOpObj.LifestyleDetail = $scope.PreOpObj.LifestyleHistory || [];
        var checkInvArray = $filter("filter")($scope.TemplateList, { "CategoryId": 2 }, true);
        var subVisionArray = checkInvArray[0].CategoryDetails;
        subVisionArray = subVisionArray.filter((x) => x.SubCategoryId == 3 || x.SubCategoryId == 4 || x.SubCategoryId == 7 || x.SubCategoryId == 69 || x.SubCategoryId == 73);
        var CategoryList = [];
        CategoryList = subVisionArray || [];
        angular.forEach(CategoryList, function (citem) {
            citem.IsSubCategoryChecked = true;
        });
        // var ScreenObj = "ASC";
        var ScreenObj = {
            "TypeId": 4,
            "TypeName": 'Pre-Op',
            "ScreenType": "Preop",
            "IsComingfrm": "Preop",
        }
        $scope.modalROSInstance = $uibModal.open({
            //"templateUrl": "templates/uibpopups/ROSpopupadding.html",
            "templateUrl": "templates/uibpopups/ROSAddinQuickAccess.html",

            "controller": "USPreAdmROSCtrl",
            "resolve": {
                "RosObject": function () { return item; },
                "CategoryList": function () { return CategoryList; },
                "cacheStorageItem": function () { return angular.copy($scope.PreOpObj) },
                "ROSIsNormalArray": function () { return angular.copy($scope.ROSIsNormalArray) },
                "ScreenObj": function () { return ScreenObj },
                "ParentObj": function () { return $scope.ParentObj; },

            },
            "backdrop": "static",
            "keyboard": false,
            // "windowClass": "newassessmentspopupuib",
            "windowClass": "modal__popup--1 bottom-to-top-modal in",
        });
        $scope.modalROSInstance.result.then(function (resp) {
            console.log(resp);
            if (resp.ROSOverAllRemarks != "" && resp.ROSOverAllRemarks != null) {
                $scope.PreOpObj.ROSOverAllRemarks = resp.ROSOverAllRemarks;
            }

            $scope.PreOpObj.AllergyRemarks = resp.AllergyRemarks || '';
            $scope.PreOpObj.SurgicalRemarks = resp.SurgicalRemarks || '';
            $scope.PreOpObj.CurrentEyeRemarks = resp.CurrentEyeRemarks || '';
            $scope.PreOpObj.CurrentSystemicRemarks = resp.CurrentSystemicRemarks || '';
            $scope.PreOpObj.SystemicHistoryRemarks = resp.SystemicHistoryRemarks || '';
            $scope.PreOpObj.LifestyleHistoryRemarks = resp.LifestyleHistoryRemarks || '';

            $scope.PreOpObj.MentalStatus = resp.SystemicOtherData.MentalStatus || '';

            if (resp.type == "RosHistory") {
                if (resp.AllergyItems.length != 0) {
                    $scope.PreOpObj.AllergyItems = [];
                    angular.forEach(resp.AllergyItems, function (kitem) {
                        kitem.SelectedReaction = kitem.SelectedReaction || "";
                        if (kitem.SelectedReaction != "") {
                            //kitem.ReactionName = kitem.SelectedReaction.AllergyReaction || "";
                            //kitem.ReactionId = kitem.SelectedReaction.ROSAllergyReactionsId || "";
                        } else {
                            kitem.ReactionName = kitem.ReactionName || "";
                        }
                        $scope.PreOpObj.AllergyItems.push(kitem);
                    });
                } else {
                    $scope.PreOpObj.AllergyItems = [];
                }
                if (resp.SystemicHistoryArray.length != 0) {
                    $scope.PreOpObj.SystemicHistory = [];
                    angular.forEach(resp.SystemicHistoryArray, function (kitem) {
                        $scope.PreOpObj.SystemicHistory.push(kitem);
                    });
                } else {
                    $scope.PreOpObj.SystemicHistory = [];
                }
                if (resp.SystemicHistoryArray.length > 0) {
                    $scope.PreOpObj.SystemicHistory = $filter('filter')(resp.SystemicHistoryArray, function (item) {
                        return item.IsChecked == true || item.DeleteInd == 'Y';
                    }) || [];
                }
                if (resp.SurgicalHistoryArray.length != 0) {
                    $scope.PreOpObj.SurgicalHistory = [];
                    angular.forEach(resp.SurgicalHistoryArray, function (kitem) {
                        $scope.PreOpObj.SurgicalHistory.push(kitem);
                    });
                } else {
                    $scope.PreOpObj.SurgicalHistory = [];
                }


                if (resp.CurrentSystemicMedicationsHistory.length != 0) {
                    
                    $scope.PreOpObj.CurrentSystemicMedicationsHistory = angular.copy(resp.CurrentSystemicMedicationsHistory);
                } else {
                    $scope.PreOpObj.CurrentSystemicMedicationsHistory = [];
                }
                if (resp.CurrentEyeMedicationArray.length != 0) {
                    $scope.PreOpObj.CurrentEyeMedications = angular.copy(resp.CurrentEyeMedicationArray);
                }
                else {
                    $scope.PreOpObj.CurrentEyeMedications = [];
                }
                if (resp.LifestyleHistory != undefined) {
                    //  $scope.LifestyleDetail.PatientDetailId = resp.LifestyleHistory.PatientDetailId || 0;
                    $scope.PreOpObj.LifestyleHistory = [];
                    $scope.PreOpObj.LifestyleHistory = angular.copy(resp.LifestyleHistory);


                    if ($scope.PreOpObj.LifestyleHistory.length > 0) {
                        $scope.HealthPhysical.LifeStyelInd = true;
                        $scope.AccordianStatusObj.IsHPSocialOpen = true;
                        angular.forEach($scope.PreOpObj.LifestyleHistory, function (item) {

                            if (item.HistoryId == 1) {
                                //  $scope.HealthPhysical.LifestyleHistory.SmokingType = item.SmokingType;

                                if (item.SmokingFromDate != '' && item.SmokingFromDate != null) {
                                    item.SmokeShowDateFormat = true;
                                    item.SmokingFromDate = $filter('date')(item.SmokingFromDate, "MM-dd-yyyy");
                                }
                            }

                            if (item.HistoryId == 2) {
                                //  $scope.HealthPhysical.LifestyleHistory.AlcoholType = item.AlcoholType;

                                if (item.AlcoholDurationDate != '' && item.AlcoholDurationDate != null) {
                                    item.AlcoShowDateFormat = true;
                                    item.AlcoholDurationDate = $filter('date')(item.AlcoholDurationDate, "MM-dd-yyyy");
                                }

                            }
                            if (item.HistoryId == 3) {
                                //  $scope.HealthPhysical.LifestyleHistory.DrugType = item.DrugType;

                                if (item.DrugDurationDate != '' && item.DrugDurationDate != null) {
                                    item.DrugShowDateFormat = true;
                                    item.DrugDurationDate = $filter('date')(item.DrugDurationDate, "MM-dd-yyyy");
                                }
                            }
                            if (item.HistoryId == 4) {
                                //   $scope.HealthPhysical.LifestyleHistory.PsychisType = item.PsychisType;
                            }

                        });
                    } else {
                        $scope.HealthPhysical.LifeStyelInd = false;
                    }


                }

                $scope.PreOpObj.isNKASelected = resp.isNKASelected || false;
                $scope.PreOpObj.isNKDASelected = resp.isNKDASelected || false;

            }

        }, function () { });
    };

    $scope.medicationcordinatorclick = function (Type) {
        Type = Type || 'PreSurgery';
        let initObj = {
            "CurrentMedicationList": $scope.PreOpObj.CurrentMedicationList || [],
            "MedicationsList": $scope.PreOpObj.MedicationsList || [],
            "InvestigationsList": $scope.PreOpObj.InvestigationsList || []
        };
        $scope.mInstancecoordinationAdd = $uibModal.open({
            "templateUrl": "templates/uibpopups/cordinationviewpopup.html",
            "controller": "UScoordinationviewpopupCtrl",
            "backdrop": "static",
            "keyboard": false,
            "resolve": {
                "cache": function () { return angular.copy(initObj) },
                "Type": function () { return angular.copy(Type) },
                "ScreenType": function () { return '' },
                "IsComingFrom": function () { return 'PreOp' },
            },
            // "windowClass": "newassessmentspopupuib",
            "windowClass": "modal__popup--1 bottom-to-top-modal in",
        });

        $scope.mInstancecoordinationAdd.result.then(function (resp) {
            if (resp.PreMedicationslist.length !== 0) {
                $scope.PreOpObj.MedicationsList = resp.PreMedicationslist || [];
                //angular.forEach($scope.PreOpObj.MedicationsList, function (item) {
                //    item.PreOpCurrentMedicationId = 0;
                //});
            }
            if (resp.CurrentMedicationslist.length !== 0) {
                $scope.IsContinuationMedication = false;
                $scope.IsStopMedication = false;
                $scope.PreOpObj.CurrentMedicationList = resp.CurrentMedicationslist || [];
                angular.forEach($scope.PreOpObj.CurrentMedicationList, function (item) {
                    if (item.DeleteInd == "N") {
                        if (item.MedicationType == 'Continuation') {
                            $scope.IsContinuationMedication = true;
                        }
                        if (item.MedicationType == 'Stop') {
                            $scope.IsStopMedication = true;
                        }
                    }
                });
            }
            if (resp.Investigationslist.length !== 0) {
                $scope.PreOpObj.InvestigationsList = resp.Investigationslist || [];
                //angular.forEach($scope.PreOpObj.InvestigationsList, function (item) {
                //    item.PatientPreOpInvestigationId = 0;
                //});
            }
        }, function () { });
    };

