    $scope.GetOrganizationASCCheckListData = function () {
        let req = {
            "ParentOrganizationId": $scope.ParenthospitalId,
            "CheckListModuleId": 1,
            "GetAllIndicator": 1
        };
        eHnoteSurgeryService.GetOrganizationASCCheckListData(req).then(function (resp) {
            if (resp.data.status === "Success") {
                $scope.PreOpObj.OrgASCChecklist = resp.data.rows;
                angular.forEach($scope.PreOpObj.OrgASCChecklist, function (item) {
                    angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                        kitem.IsChecked = false;
                    });
                });

                $scope.PreOpObj.ChunkedGeneralChecklist = [];
                //let tempArrayGeneral = $filter('filter')($scope.PreOpObj.OrgASCChecklist, { 'CheckListCategoryId': 6 }, true);

                let tempArrayGeneral = $scope.PreOpObj.OrgASCChecklist
                    .filter(item =>
                        item.CheckListCategoryId === 6
                    )
                    .sort((a, b) => a.OrgOrderBy - b.OrgOrderBy);

                let filteredClinicalChecklist1 = angular.copy(tempArrayGeneral);
                if (filteredClinicalChecklist1.length > 0) {
                    let chunkSize = Math.ceil((filteredClinicalChecklist1.length) / 2);
                    for (let i = 0; i < filteredClinicalChecklist1.length; i += chunkSize) {
                        $scope.PreOpObj.ChunkedGeneralChecklist.push(filteredClinicalChecklist1.slice(i, i + chunkSize));
                    }
                }
                $scope.PreOpObj.ChunkedClinicalChecklist = [];
                //let tempArray = $filter('orderBy')($filter('filter')($scope.PreOpObj.OrgASCChecklist, { CheckListCategoryId: 1, CheckListSubTypeId: 1 }, true), 'OrgOrderBy', true);

                let tempArray = $scope.PreOpObj.OrgASCChecklist
                    .filter(item =>
                        item.CheckListCategoryId === 1 &&
                        item.CheckListSubTypeId === 1
                    )
                    .sort((a, b) => a.OrgOrderBy - b.OrgOrderBy);

                let filteredClinicalChecklist = angular.copy(tempArray);
                if (filteredClinicalChecklist.length > 0) {
                    let chunkSize = Math.ceil((filteredClinicalChecklist.length) / 2);
                    for (let i = 0; i < filteredClinicalChecklist.length; i += chunkSize) {
                        $scope.PreOpObj.ChunkedClinicalChecklist.push(filteredClinicalChecklist.slice(i, i + chunkSize));
                    }
                }


                if ($scope.IsAddChecklistTemplate) {
                    let recheckreq = {
                        "OrganizationId": $scope.HospitalId,
                        "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
                        "PatientId": $scope.cacheStorageItem.PatientID || null,
                        "PatientSurgeryId": $scope.SurgeryDiagnosisObj.SelectedSurgery.PatientSurgeryId || null
                    };
                    eHnoteSurgeryService.GetPreOpChartData(recheckreq).then(function (resp) {

                        if (resp.data.Status === "Success") {
                            if (resp.data.rows.length > 0) {
                                var data = resp.data.rows[0];
                                // checklists
                                if (data.OrgASCChecklist.length > 0) {
                                    angular.forEach(data.OrgASCChecklist, function (item) {
                                        angular.forEach($scope.PreOpObj.OrgASCChecklist, function (hitem) {
                                            if (hitem.CheckListCategoryId === item.CheckListCategoryId) {
                                                angular.forEach(hitem.OrganizationCheckListDetails, function (kitem) {
                                                    if (kitem.Value == item.Value && kitem.CheckListId === item.CheckListId) {
                                                        kitem.IsChecked = true;
                                                        hitem.PatientAscCheckListDetailId = item.PatientAscCheckListDetailId || 0;
                                                        Kitem.PatientAscCheckListDetailId = item.PatientAscCheckListDetailId || 0;
                                                    }
                                                });
                                            }
                                        });
                                    });
                                }
                            }


                            $scope.OrgASCChecklist = $scope.OrgASCChecklist || [];
                            if (data.OrgASCChecklist.length > 0) {
                                $scope.OrgASCChecklist = data.OrgASCChecklist || [];
                            } else {
                                $scope.OrgASCChecklist = [];
                            }


                        }
                        $scope.IsAddChecklistTemplate = false;
                    });
                }
            }

        }, function (err) {
            console.log(err);
        });

    };

