    $scope.Preopmedicationspopup = function () {
        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/uibpopups/Preopmedicationspopup.html",
            "backdrop": "static",
            "scope": $scope,
            "keyboard": false,
            //"windowClass": "newassessmentspopupuib",
            "windowClass": "modal__popup--1 bottom-to-top-modal in",
            "controller": function ($scope, $uibModal, $uibModalInstance, eHnotePatientPVService) {
                $scope.closeuib = function () {
                    //$uibModalInstance.dismiss("cancel");
                    $uibModalInstance.close("close");
                };
                $scope.SelectedPreOpMedicationsList = [];
                $scope.PreOpTemplateName = "";


                $scope.GetPreOpMedicationObj = function () {
                    return {
                        "MedicineObject": "",
                        "MedicationId": null,
                        "OrganizationMedicationId": null,
                        "MedicationName": "",
                        "DeleteInd": "N",
                        "FrequencyId": null,
                        "DoseId": null,
                        "DoseUnitId": null
                    };
                };
                $scope.PreOpMedicationObj = angular.copy($scope.GetPreOpMedicationObj());

                $scope.getOrgMedicines = function (text) {
                    text = text || "";
                    var object = {
                        "LevelType": "O",
                        "HospitalId": $scope.HospitalId,
                        "UserId": $scope.UserId,
                        "SpecializationId": $scope.SpecializationId,
                        "SearchText": text,
                        "PageSize": 10,
                        "PageNumber": 1,
                        "Type": '',
                        "ParentOrganizationId": $scope.ParenthospitalId || null
                    };
                    //if (text === "") {
                    //    object.Type = 'C';
                    //}
                    return eHnoteSettingsDataService.GetMasterMedicines(object).then(function (response) {
                        if (response.data.count !== 0) {
                            if (response.data.MedicineList !== undefined) {
                                return response.data.MedicineList.map(function (item) {
                                    return item;
                                });
                            }
                        }
                    });

                }

                $scope.AddPreOpOrgMedication = function (Obj) {

                    let reqobj = {
                        "UserId": $scope.UserId,
                        "ParentOrganizationId": $scope.ParenthospitalId,
                        "ASCOrganizationMedicationId": 0,
                        "MedicationId": Obj.MedicineObject.MedicineId,
                        "OrganizationMedicationId": Obj.MedicineObject.OrganizationPrescriptionId,
                        "MedicationName": Obj.MedicineObject.MedicineName,
                        "DoseId": Obj.DoseId,
                        "DoseUnitId": Obj.DoseUnitId,
                        "FrequencyId": Obj.FrequencyId,
                        "DeleteInd": "N"
                    };
                    console.log(reqobj);
                    eHnoteSurgeryService.AddUpdateOrganizationPreOpMedications(reqobj).then(function (resp) {
                        if (resp.data.status === "Success") {
                            $scope.PreOpMedicationObj = angular.copy($scope.GetPreOpMedicationObj());
                            $scope.GetOrganizationPreOpMedications();
                        }
                    }, function (err) {
                        console.log(err);
                    });
                };

                $scope.DeletePreOpMedication = function (Obj, ind) {
                    let reqobj = {
                        "UserId": $scope.UserId,
                        "ParentOrganizationId": $scope.ParenthospitalId,
                        "ASCOrganizationMedicationId": Obj.ASCOrganizationMedicationId,
                        "MedicationId": Obj.MedicationId,
                        "OrganizationMedicationId": Obj.OrganizationMedicationId,
                        "MedicationName": Obj.MedicationName,
                        "DoseId": Obj.DoseId,
                        "DoseUnitId": Obj.DoseUnitId,
                        "FrequencyId": Obj.FrequencyId,
                        "DeleteInd": "Y"
                    };
                    console.log(reqobj);
                    eHnoteSurgeryService.AddUpdateOrganizationPreOpMedications(reqobj).then(function (resp) {
                        if (resp.data.status === "Success") {
                            $scope.PreOpMedicationObj = angular.copy($scope.GetPreOpMedicationObj());
                            $scope.GetOrganizationPreOpMedications();
                        }
                    }, function (err) {
                        console.log(err);
                    });
                };

                $scope.SavePreOpMedicationTemplate = function () {
                    if ($scope.PreOpTemplateName == "") {
                        alertify.error("Please enter a template name!");
                        return;
                    }
                    alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre pl-20 pr-20'>Are you sure you want to save the template? </h4>",
                        function () {
                            let obj = {
                                "UserId": $scope.UserId,
                                "UserMedicationTemplateId": 0,
                                "TemplateName": $scope.PreOpTemplateName,
                                "DeleteInd": "N",
                                "TemplateDetails": []
                            };
                            let templateobj;
                            angular.forEach($scope.PreOpObj.PreOpMedications, function (hitem) {
                                if (hitem.IsChecked) {
                                    templateobj = {
                                        "UserMedicationTemplateDetailId": 0,
                                        "UserMedicationTemplateId": 0,
                                        "OrganizationMedicationId": hitem.OrganizationMedicationId,
                                        "MedicationId": hitem.MedicationId,
                                        "DeleteInd": "N",
                                        /* "MedicationName": hitem.MedicationName,*/
                                        //"DoseId": hitem.DoseId,
                                        //"DoseUnitId": hitem.DoseUnitId,
                                        //"FrequencyId": hitem.FrequencyId,
                                    };
                                    obj.TemplateDetails.push(templateobj);
                                }
                            });
                            if (obj.TemplateDetails.length === 0) {
                                alertify.error("Please select atleast one medication!");
                                return;
                            }
                            eHnoteSurgeryService.AddUpdateUserPreOpMedicationTemplates(obj).then(function (resp) {
                                if (resp.data.status === "Success") {
                                    $scope.GetUserPreOpMedicationTemplateDetailsInpopup();
                                }
                            }, function () {

                            });
                        }, function () {

                        });
                };

                $scope.PushfreqMedicalItems = function (obj) {
                    $scope.PreOpMedicationObj.MedicineObject = $scope.PreOpMedicationObj.MedicineObject || "";
                };

                $scope.OnselectMedicationTemplate = function (obj) {
                    obj.TemplateDetails = obj.TemplateDetails || [];
                    if (obj.TemplateDetails.length === 0) {
                        return false;
                    }
                    angular.forEach($scope.PreOpObj.PreOpMedications, function (item) {
                        item.IsChecked = false;
                    });
                    angular.forEach($scope.PreOpObj.PreOpMedications, function (item) {
                        angular.forEach(obj.TemplateDetails, function (subitem) {
                            if (subitem.MedicationId == item.MedicationId) {
                                item.IsChecked = true;
                            }
                        });
                    });

                };

                $scope.GetUserPreOpMedicationTemplateDetailsInpopup = function () {
                    let obj = {
                        "UserId": $scope.UserId
                    };
                    eHnoteSurgeryService.GetUserPreOpMedicationTemplateDetails(obj).then(function (resp) {
                        if (resp.data.status === "Success") {
                            alertify.success("Template saved successfully!");
                            $scope.PreOpMedicationTemplates = resp.data.rows;
                        }
                    }, function (err) {

                    });
                };

                $scope.getMasterFieldDosageData();

            },
            //"resolve": {
            //    "DoseArray": function () {
            //        return $scope.DoseArray;
            //    },
            //    "FrequencyArray": function () {
            //        return $scope.FrequencyArray;
            //    },
            //    "DoseUnitArray": function () {
            //        return $scope.DoseUnitArray;
            //    }
            //}
        });
        $scope.mInstanceAdd.result.then(function (data) {
            $scope.GetUserPreOpMedicationTemplateDetails();
        }, function (data) {
            console.log(data);
        });
    }


    $scope.SelectIVArm = function (val, item) {
        if (val == 1) {
            if (item.IVArm == "" || item.IVArm == "LeftArm" || item.IVArm == "RightWrist" || item.IVArm == "LeftWrist") {
                item.IVArm = "RightArm";
            } else {
                item.IVArm = "";

            }
        }
        if (val == 2) {
            if (item.IVArm == "" || item.IVArm == "RightArm" || item.IVArm == "RightWrist" || item.IVArm == "LeftWrist") {
                item.IVArm = "LeftArm";
            } else {
                item.IVArm = "";

            }
        }
        if (val == 3) {
            if (item.IVArm == "" || item.IVArm == "RightArm" || item.IVArm == "LeftArm" || item.IVArm == "LeftWrist") {
                item.IVArm = "RightWrist";
            } else {
                item.IVArm = "";

            }
        }
        if (val == 4) {
            if (item.IVArm == "" || item.IVArm == "RightArm" || item.IVArm == "LeftArm" || item.IVArm == "RightWrist") {
                item.IVArm = "LeftWrist";
            } else {
                item.IVArm = "";

            }
        }

    }

    $scope.OnPreOpChecklistSelect = function (obj, parentobj) {
        var CheckListInd = false;
        angular.forEach(parentobj.OrganizationCheckListDetails, function (item) {
            if (obj.IsChecked == true && item.Value == obj.Value) {
                CheckListInd = true;
                item.PatientAscCheckListDetailId = item.PatientAscCheckListDetailId || null;
                if (item.PatientAscCheckListDetailId != null) {
                    item.DeleteInd = "Y";
                }
            } else {
                item.IsChecked = false;
            }
        })

        if (CheckListInd == true) {
            obj.IsChecked = false;
            parentobj.IsChecked = false;


            if (parentobj.CheckListCategoryId === 1) {
                $scope.PreOpObj.IsAllNurseCheckListChecked = '';
            }
            if (parentobj.CheckListCategoryId === 5) {
                $scope.PreOpObj.IsAllMedicineCheckListChecked = '';
            }
            if (parentobj.CheckListCategoryId === 6) {
                $scope.PreOpObj.IsAllGeneralCheckListChecked = '';
            }


        } else {
            obj.IsChecked = true;
            parentobj.IsChecked = true;
            if (parentobj.Value == "Others") {
                parentobj.Remarks = "";
            }
            parentobj.Value = obj.Value || '';
            parentobj.ChecklistDate = null;
        }

        if (parentobj.CheckListCategoryId === 1) {
            if (obj.Value !== "N/A" && obj.Value !== "No" && obj.Value !== "Not") {
                parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
            }
            if (obj.Value == "Yes" || obj.Value == "Reviewed" || obj.Value == "Done") {
                $scope.PreOpObj.IsAllNurseCheckListChecked = $scope.PreOpObj.IsAllNurseCheckListChecked == 1 ? $scope.PreOpObj.IsAllNurseCheckListChecked : '';
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                $scope.PreOpObj.IsAllNurseCheckListChecked = $scope.PreOpObj.IsAllNurseCheckListChecked == 2 ? $scope.PreOpObj.IsAllNurseCheckListChecked : '';
            }
            if (obj.Value == "N/A") {
                $scope.PreOpObj.IsAllNurseCheckListChecked = $scope.PreOpObj.IsAllNurseCheckListChecked == 3 ? $scope.PreOpObj.IsAllNurseCheckListChecked : '';
            }

            if (obj.CheckListId == 12 && obj.Value !== "Yes") {
                $scope.PreOpObj.NPOTime = '';
            }
        }
        if (parentobj.CheckListCategoryId === 6) {
            if (obj.Value == "Yes" || obj.Value == "Reviewed" || obj.Value == "Done") {
                $scope.PreOpObj.IsAllGeneralCheckListChecked = $scope.PreOpObj.IsAllGeneralCheckListChecked == 1 ? $scope.PreOpObj.IsAllGeneralCheckListChecked : '';
                parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                $scope.PreOpObj.IsAllGeneralCheckListChecked = $scope.PreOpObj.IsAllGeneralCheckListChecked == 2 ? $scope.PreOpObj.IsAllGeneralCheckListChecked : '';
            }
            if (obj.Value == "N/A") {
                $scope.PreOpObj.IsAllGeneralCheckListChecked = $scope.PreOpObj.IsAllGeneralCheckListChecked == 3 ? $scope.PreOpObj.IsAllGeneralCheckListChecked : '';
            }
        }
        if (parentobj.CheckListCategoryId === 5) {
            if (obj.Value == "Yes" || obj.Value == "Reviewed" || obj.Value == "Done") {
                $scope.PreOpObj.IsAllMedicineCheckListChecked = $scope.PreOpObj.IsAllMedicineCheckListChecked == 1 ? $scope.PreOpObj.IsAllMedicineCheckListChecked : '';
                if (parentobj.CheckListId == 40) {
                    parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
                }
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                $scope.PreOpObj.IsAllMedicineCheckListChecked = $scope.PreOpObj.IsAllMedicineCheckListChecked == 2 ? $scope.PreOpObj.IsAllMedicineCheckListChecked : '';
            }
            if (obj.Value == "N/A") {
                $scope.PreOpObj.IsAllMedicineCheckListChecked = $scope.PreOpObj.IsAllMedicineCheckListChecked == 3 ? $scope.PreOpObj.IsAllMedicineCheckListChecked : '';
            }
        }
        if ($scope.PreOpObj.IsAllNurseCheckListChecked === '' || $scope.PreOpObj.IsAllGeneralCheckListChecked === '' || $scope.PreOpObj.IsAllMedicineCheckListChecked === '') {
            $scope.PreOpObj.IsAllCheckListChecked = '';
        }
        if (parentobj.CheckListCategoryId === 25) {
            if (obj.Value !== "N/A" && obj.Value !== "No" && obj.Value !== "Not") {
                parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
            } else {
                parentobj.ChecklistTime = "";
            }
        };
    };

