    $scope.SaveTemplateName = function (val) {

        if (val == 1) {
            $scope.PreOpObj.ChecklistTemplateName = $scope.PreOpObj.ClinicalChecklistTemplateName || "";
        }
        if (val == 5) {
            $scope.PreOpObj.ChecklistTemplateName = $scope.PreOpObj.MedicationChecklistTemplateName || "";
        }
        if (val == 6) {
            $scope.PreOpObj.ChecklistTemplateName = $scope.PreOpObj.GeneralChecklistTemplateName || "";
        }
        if (val == 12) {
            $scope.PreOpObj.ChecklistTemplateName = $scope.PreOpObj.PatientChecklistTemplateName || "";
        }

        if ($scope.PreOpObj.ChecklistTemplateName === "") {
            alertify.error("Please enter template name!");
            return false;
        } else {
            let templateReq = {
                "UserId": $scope.UserId,
                "HospitalId": $scope.HospitalId,
                "UserPreOpCheckListTemplateId": 0,
                "TemplateName": $scope.PreOpObj.ChecklistTemplateName || "",
                "CheckListCategoryId": val,
                "DeleteInd": "N",
                "TemplateDetails": [],
                "RoleId": $scope.RoleId || null
            };


            if (val === 6) {
                angular.forEach($scope.PreOpObj.ChunkedGeneralChecklist, function (hitem) {
                    angular.forEach(hitem, function (item) {
                        angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                            if (kitem.IsChecked) {
                                let obj = {
                                    "UserPreOpCheckListTemplateDetailId": 0,
                                    "UserPreOpCheckListTemplateId": 0,
                                    "CheckListId": item.CheckListId,
                                    "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                                    "OrganizationPreOpCheckListValueId": kitem.OrganizationPreOpCheckListValueId,
                                    "DeleteInd": "N"
                                };
                                templateReq.TemplateDetails.push(obj);
                            }
                        });
                    });
                });
            } else if (val === 1) {
                //let ConcernedChecklistArray = $filter('filter')($scope.PreOpObj.OrgASCChecklist, { 'CheckListCategoryId': val }, true);
                angular.forEach($scope.PreOpObj.ChunkedClinicalChecklist, function (hitem) {
                    angular.forEach(hitem, function (item) {
                        angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                            if (kitem.IsChecked) {
                                let obj = {
                                    "UserPreOpCheckListTemplateDetailId": 0,
                                    "UserPreOpCheckListTemplateId": 0,
                                    "CheckListId": item.CheckListId,
                                    "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                                    "OrganizationPreOpCheckListValueId": kitem.OrganizationPreOpCheckListValueId,
                                    "DeleteInd": "N"
                                };
                                templateReq.TemplateDetails.push(obj);
                            }
                        });
                    });
                });
            } else if (val === 12) {
                let ConcernedChecklistArray = $filter('filter')($scope.PreOpObj.OrgASCChecklist, { 'CheckListCategoryId': val }, true);
                angular.forEach(ConcernedChecklistArray, function (item) {
                    angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                        if (kitem.IsChecked) {
                            let obj = {
                                "UserPreOpCheckListTemplateDetailId": 0,
                                "UserPreOpCheckListTemplateId": 0,
                                "CheckListId": item.CheckListId,
                                "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                                "OrganizationPreOpCheckListValueId": kitem.OrganizationPreOpCheckListValueId,
                                "DeleteInd": "N"
                            };
                            templateReq.TemplateDetails.push(obj);
                        }
                    });
                });
            } else {
                let ConcernedChecklistArray = $filter('filter')($scope.PreOpObj.OrgASCChecklist, { 'CheckListCategoryId': val }, true);
                angular.forEach(ConcernedChecklistArray, function (item) {
                    angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                        if (kitem.IsChecked) {
                            let obj = {
                                "UserPreOpCheckListTemplateDetailId": 0,
                                "UserPreOpCheckListTemplateId": 0,
                                "CheckListId": item.CheckListId,
                                "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                                "OrganizationPreOpCheckListValueId": kitem.OrganizationPreOpCheckListValueId,
                                "DeleteInd": "N"
                            };
                            templateReq.TemplateDetails.push(obj);
                        }
                    });
                });
            }

            templateReq.TemplateDetails = templateReq.TemplateDetails || [];
            if (templateReq.TemplateDetails.length === 0) {
                alertify.error("Please select checklist values!");
                return false;
            }
            eHnoteSurgeryService.AddUpdatePreOpCheckListTemplates(templateReq).then(function (resp) {
                if (resp.data.status === "Success") {
                    alertify.success("Template saved successfully!");
                    if (val === 1) {
                        $scope.GetPreOpNurseCheckListTemplates();
                        $scope.isOpenClinicalChecklistPopOver = false;
                        $scope.PreOpObj.ClinicalChecklistTemplateName = '';
                    }
                    if (val === 5) {
                        $scope.GetPreOpMedicineCheckListTemplates();
                        $scope.isOpenMedicationChecklistPopOver = false;
                        $scope.PreOpObj.MedicationChecklistTemplateName = ''
                    }
                    if (val === 6) {
                        $scope.GetPreOpGeneralCheckListTemplates();
                        $scope.isOpenGeneralChecklistPopOver = false;
                        $scope.PreOpObj.GeneralChecklistTemplateName = '';

                    }
                    if (val === 12) {
                        $scope.GetPreOpPatientCheckListTemplates();
                        $scope.IsOpenCheckinChecklist = false;
                        $scope.PreOpObj.PatientChecklistTemplateName = '';
                    }
                }
                if (resp.data.status === "Failure") {
                    alertify.error(resp.data.Message)
                }
            }, function (err) {
                console.log(err);
            });
        }
    };
