    $scope.scanFiles = function () {

        let PatientSurgeryId = null;
        if ($scope.cacheStorageItem.AppointmentTypeId == 7) {
            if ($scope.cacheStorageItem.PreAdmSurgeryList.length > 0) {
                PatientSurgeryId = $scope.cacheStorageItem.PreAdmSurgeryList[0].PatientSurgeryId;
            }
        } else if ($scope.cacheStorageItem.AppointmentTypeId == 4 || $scope.cacheStorageItem.AppointmentTypeId == 14) {
            if ($scope.cacheStorageItem.SurgeryList.length > 0) {
                PatientSurgeryId = $scope.cacheStorageItem.SurgeryList[0].PatientSurgeryId;
            }
        }

        var obj = {
            "PatientId": $scope.cacheStorageItem.PatientID || null,
            "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
            "VisitId": $scope.cacheStorageItem.PatientVisitId || null,
            "PatientName": $scope.MainObj.PatientDetails.FullName || '',
            "Tab": "ASCFileUploads",
            "SignedDate": $filter('date')($scope.currentDate, "yyyy-MM-dd"),
            "FileTypeId": 18,
            "FileName": '',
            "DisplayName": '',
            "PatientSurgeryId": PatientSurgeryId
        }

        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/UsNewConsultation/uibpopup/PatientDocumentScanner.html",
            "backdrop": "static",
            "scope": $scope,
            "size": "lg",
            "resolve": {
                "mainObject": function () { return obj; }
            },
            "windowClass": "modal__eighty--  ",
            "keyboard": false,
            "controller": "DocumentScannerCtrl",
        });
        $scope.mInstanceAdd.result.then(function (data) {
            console.log(data);
            if (data.Status == "Success") {
                $scope.GetPreOpChartData();
            }
        }, function (cancel) {
        });
    }
    $scope.PreOpSummaryObj = $scope.GetPreraOpSummaryObj();
    $scope.PreOpDynamicSummaryShowingInds = function (type) {
        if (type == 'ROS Main') {
            if ($scope.PreOpSummaryObj.IsShowPreOpROSInd) {
                $scope.PreOpSummaryObj.IsShowPreOpROSSystemicHistoryInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpROSSurgicalHistoryInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpROSAllergiesInd = true;
            }
            else {
                $scope.PreOpSummaryObj.IsShowPreOpROSSystemicHistoryInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpROSSurgicalHistoryInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpROSAllergiesInd = false;
            }
        }
        if (type == 'Pre Admission Orders') {
            if ($scope.PreOpSummaryObj.IsShowPreOpPreAdmissionOrdersInd) {
                $scope.PreOpSummaryObj.IsShowPreOpPreAdmissionPreSurgiesMedicationInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpPreAdmissionOrdersCurrentMedicationInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpPreAdmissionOrdersLabInvestigationInd = true;
            }
            else {
                $scope.PreOpSummaryObj.IsShowPreOpPreAdmissionPreSurgiesMedicationInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpPreAdmissionOrdersCurrentMedicationInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpPreAdmissionOrdersLabInvestigationInd = false;
            }
        }
        if (type == 'Check List Show') {
            if ($scope.PreOpSummaryObj.IsShowPreOpCheckListInd) {
                $scope.PreOpSummaryObj.IsShowPreOpCheckListHealthPhysicalInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListAldarateScoreInd = true;
            }
            else {
                $scope.PreOpSummaryObj.IsShowPreOpCheckListHealthPhysicalInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListAldarateScoreInd = false;
            }
        }
        if (type == 'Check List Main') {
            if ($scope.PreOpSummaryObj.IsShowPreOpCheckListMainInd) {
                $scope.PreOpSummaryObj.IsShowPreOpCheckListNurseInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListGeneralInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListMedicationInd = true;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListReviewedByInd = true;
            }
            else {
                $scope.PreOpSummaryObj.IsShowPreOpCheckListNurseInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListGeneralInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListMedicationInd = false;
                $scope.PreOpSummaryObj.IsShowPreOpCheckListReviewedByInd = false;
            }
        }
        if (type == 'Action') {
            if ($scope.PreOpSummaryObj.IsShowPreOpActionInd) {
                $scope.PreOpSummaryObj.IsShowPreOPActionPreOpcallInd = true;
                $scope.PreOpSummaryObj.IsShowPreOPActionPreOpMediactionInd = true;
                $scope.PreOpSummaryObj.IsShowPreOPActionPreOpPatientInd = true;
                $scope.PreOpSummaryObj.IsShowPreOPActionReviewedByInd = true;
            }
            else {
                $scope.PreOpSummaryObj.IsShowPreOPActionPreOpcallInd = false;
                $scope.PreOpSummaryObj.IsShowPreOPActionPreOpMediactionInd = false;
                $scope.PreOpSummaryObj.IsShowPreOPActionPreOpPatientInd = false;
                $scope.PreOpSummaryObj.IsShowPreOPActionReviewedByInd = false;
            }
        }
    }

