    $scope.OpenVitalsPopUp = function (item) {
        let givenVitalsArray = angular.copy($scope.PreOpObj.Vitals);
        let DocumentDetails = angular.copy(item.DocumentDetails);

        let PerformedArray = angular.copy($scope.PerformedByArray);
        //let DocumentDetails = [];
        let TypeObj = {
            "TypeId": 4,
            "TypeName": "Pre-op",
            "IsComingfrom": "Pre-op",
            "AdmitVitalsArray": $scope.PreOpObj.AdmitVitalsArray || [],
        }
        let modalInstance = $uibModal.open({
            "templateUrl": "templates/ASC/ASCVitalsPopUp.html",
            "controller": "USASCVitalsPopUpCtrl",
            "resolve": {
                "VitalsArrayList": function () { return givenVitalsArray || {}; },
                "PerformedByArray": function () { return PerformedArray || {}; },
                "DocumentDetails": function () { return DocumentDetails || []; },
                "allUserList": function () { return $scope.allUserList || {}; },
                "UserId": function () { return $scope.UserId },
                "VitalInd": function () { return false },
                "TypeObj": function () { return TypeObj },
            },

            "windowClass": "modal__popup--1 bottom-to-top-modal in",
            "backdrop": "static",
            //"scope": $scope,
            "keyboard": false
        });
        modalInstance.result.then(function (data) {
            //  $scope.PreOpObj.Vitals = angular.copy(data);
            if (data.VitalsArray.length > 0) {
                angular.forEach(data.VitalsArray, function (vitem) {
                    vitem.TypeId = 4;
                });
                $scope.PreOpObj.Vitals = angular.copy(data.VitalsArray);
            }

            if ($scope.PreOpObj.Vitals.length > 0) {
                $scope.PreOpObj.VitalsDisplay = $scope.GetDisplayVitalsArray();
                angular.forEach($scope.PreOpObj.Vitals, function (mainitem, $index) {

                    let ndate = moment().format("YYYY-MM-DD");
                    let edate = ndate + " " + mainitem.VitalAddTime;
                    mainitem.VitalAddTime = moment(edate, "YYYY-MM-DD HH:mm").format("hh:mm A");

                    if (mainitem.DeleteInd == 'N') {
                        let TempFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 11 }, true) || [];
                        if (TempFilter.length > 0) {
                            var tempobj = {
                                "value": TempFilter[0].Value,
                                "UnitTypeName": TempFilter[0].UnitTypeName
                            }
                        }
                        $scope.PreOpObj.VitalsDisplay[0].Values.push(tempobj);
                        let pulseFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 12 }, true) || [];
                        if (pulseFilter.length > 0) {
                            var pulseobj = {
                                "value": pulseFilter[0].Value,
                                "UnitTypeName": pulseFilter[0].UnitTypeName
                            }
                        }
                        $scope.PreOpObj.VitalsDisplay[1].Values.push(pulseobj);
                        let BpUpFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 4 }, true) || [];
                        let BpLowFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 5 }, true) || [];
                        if (BpUpFilter.length > 0 || BpLowFilter.length > 0) {
                            if (BpUpFilter[0].Value != '' || BpLowFilter[0].Value != '') {
                                var Bpobj = {
                                    "value": BpUpFilter[0].Value + '/' + BpLowFilter[0].Value,
                                    "UnitTypeName": BpUpFilter[0].UnitTypeName
                                }
                            } else {
                                var Bpobj = {
                                    "value": "",
                                    "UnitTypeName": BpUpFilter[0].UnitTypeName
                                }
                            }
                        }
                        $scope.PreOpObj.VitalsDisplay[2].Values.push(Bpobj);
                        let RespFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 14 }, true) || [];
                        if (RespFilter.length > 0) {
                            var Respobj = {
                                "value": RespFilter[0].Value,
                                "UnitTypeName": RespFilter[0].UnitTypeName
                            }
                        }
                        $scope.PreOpObj.VitalsDisplay[3].Values.push(Respobj);
                        let Spo2Filter = $filter('filter')(mainitem.Vitals, { "VitalId": 15 }, true) || [];
                        if (Spo2Filter.length > 0) {
                            var Spo2obj = {
                                "value": Spo2Filter[0].Value,
                                "UnitTypeName": Spo2Filter[0].UnitTypeName
                            }
                        }
                        $scope.PreOpObj.VitalsDisplay[4].Values.push(Spo2obj);
                        let BGLFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 8 }, true) || [];
                        if (BGLFilter.length > 0) {
                            var BGLobj = {
                                "value": BGLFilter[0].Value,
                                "UnitTypeName": BGLFilter[0].UnitTypeName
                            }
                        }
                        $scope.PreOpObj.VitalsDisplay[5].Values.push(BGLobj);
                        var Time = {
                            "value": $scope.PreOpObj.Vitals[$index].VitalAddTime || "",
                            "UnitTypeName": "",
                        }
                        $scope.PreOpObj.VitalsDisplay[6].Values.push(Time);
                        var performedBy = {
                            "value": $scope.PreOpObj.Vitals[$index].UserName || "",
                            "UnitTypeName": "",
                        }
                        $scope.PreOpObj.VitalsDisplay[7].Values.push(performedBy);
                        var Notes = {
                            "value": $scope.PreOpObj.Vitals[$index].VitalRemarks || "",
                            "UnitTypeName": "",
                        }
                        $scope.PreOpObj.VitalsDisplay[8].Values.push(Notes);
                    }
                });
            }

            if (data.TempImagesArray.length > 0) {
                angular.forEach(data.TempImagesArray, function (sitem, index) {
                    $scope.FilesObj.TempImagesArray.push(sitem);
                });
            }
            if (data.DocumentDetails.length > 0) {
                $scope.FilesObj.TempImagesArray = data.DocumentDetails || [];
             
            } else {
                angular.forEach($scope.FilesObj.TempImagesArray, function (ditem, index) {
                    if (ditem.FileTypeId == 32) {
                        ditem.DeleteInd = 'Y';
                    }
                });
                angular.forEach($scope.FilesObj.TempImagesArray, function (item, index) {
                    if (item.FileTypeId == 32) {
                        item.DeleteInd = 'Y';
                    }
                });

            }
        }, function (cancel) {

        });
    };

    $scope.EditSurgery = function () {

        $scope.mInstanceAdd = $uibModal.open({
            templateUrl: "EditSurgeryStaff.html",
            "size": "lg",
            "resolve": {
                "AllUserList": function () { return $scope.allUserList; },
                "AllAnesthetistList": function () { return $scope.AnesthetistArray; },
                "AllNurseList": function () { return $scope.AllNurseList; },
                "AppointmentId": function () { return $scope.cacheStorageItem.AppointmentId; },
                "PatientSurgeryId": function () { return $scope.SurgeryDiagnosisObj.SelectedSurgery.PatientSurgeryId; },
                "SurgeonID": function () { return $scope.SurgeryDiagnosisObj.SelectedSurgery.DoctorId; },
                "SurgeryList": function () { return $scope.PreOpObj.SurgeryList; },
                "UserId": function () { return $scope.UserId; },
                "SurgeryDiagnosisObj": function () { return $scope.SurgeryDiagnosisObj; }
            },
            "controller": function ($scope, $uibModal, $uibModalInstance, AllUserList, AllAnesthetistList, AllNurseList, AppointmentId, PatientSurgeryId, SurgeonID, SurgeryDiagnosisObj, UserId) {
                $scope.EditSurgeryObj = {
                    "AllUserList": [],
                    "AllAnesthetistList": [],
                    "AllNurseList": [],
                    "UserID": null,
                    "AnesthetistID": null,
                    "NurseID": null
                }

                $scope.EditSurgeryObj.AllUserList = AllUserList;
                $scope.EditSurgeryObj.AllAnesthetistList = AllAnesthetistList;
                $scope.EditSurgeryObj.AllNurseList = AllNurseList;
                SurgeryDiagnosisObj.SurgeonID = SurgeryDiagnosisObj.SurgeonID || '';
                if (SurgeryDiagnosisObj.SurgeonID != '') {
                    $scope.EditSurgeryObj.SurgeonID = SurgeryDiagnosisObj.SurgeonID;
                } else {
                    $scope.EditSurgeryObj.SurgeonID = SurgeonID;
                }
                $scope.EditSurgeryObj.AnesthetistID = SurgeryDiagnosisObj.AnesthetistID;
                $scope.EditSurgeryObj.NurseID = SurgeryDiagnosisObj.NurseID;

                $scope.SaveEditSurgeryStaff = function (item) {
                    var obj = {
                        "PatientSurgeryID": PatientSurgeryId,
                        "AppointmentID": AppointmentId,
                        "AnesthetistID": item.AnesthetistID,
                        "NurseID": item.NurseID,
                        "SurgeonID": item.SurgeonID,
                        "UserId": UserId,
                        "AppointmentTypeId": 4,
                        "Logs": {},
                    };
                    eHnoteSurgeryService.AddUpdateSurgeryStaffList(obj).then(function (response) {
                        console.log(response);
                        if (response.data.status === "Success") {
                            $uibModalInstance.close(response);
                        }
                    });
                };

                $scope.close = function () {
                    $uibModalInstance.dismiss("cancel");
                };
            }
        });
        $scope.mInstanceAdd.result.then(function (data) {
            if (data.data.status === "Success") {
                $scope.init();
            }
        }, function (cancel) {

        });
    }

