    $scope.preopcallpopup = function (editcase, type) {

        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/uibpopups/Preopcallnewpopup.html",
            "backdrop": "static",
            "keyboard": false,
            // "windowClass": "newassessmentspopupuib",
            "windowClass": "modal__popup--1 bottom-to-top-modal in",
            "scope": $scope,
            /*"editcase": edicase,*/
            "resolve": {
                "editcase": function () { return editcase; },
                "type": function () { return type; },
            },
            // "size": "lg",
            "controller": function ($scope, $uibModal, $uibModalInstance, eHnotePatientPVService, eHnotePatientDataService, editcase, type) {
                if (type == 1) {
                    $scope.PreOpCallObj = angular.copy($scope.GetPreOpCallObj());
                } else {
                    //$scope.PreOpCallObj = angular.copy(editcase);
                    editcase = editcase || [];
                    if (editcase.length > 0) {
                        $scope.PreOpCallObj.ContactStartDate = $filter('date')(editcase[0].ContactStartDate, "MM-dd-yyyy") || '';
                        $scope.PreOpCallObj.DropStartDate = $filter('date')(editcase[0].DropStartDate, "MM-dd-yyyy") || '';
                        $scope.PreOpCallObj.PatientAscPreOpCallDetailId = editcase[0].PatientAscPreOpCallDetailId;
                        $scope.PreOpCallObj.Remarks = editcase[0].Remarks;
                        $scope.PreOpCallObj.PatientId = editcase[0].PatientId;
                        $scope.PreOpCallObj.AppointmentId = editcase[0].AppointmentId;
                        $scope.PreOpCallObj.ContactType = editcase[0].ContactType;
                        $scope.PreOpCallObj.IsConnectedWithPatient = editcase[0].IsConnectedWithPatient;
                        $scope.PreOpCallObj.IsConnectedWithFamilyOrFriend = editcase[0].IsConnectedWithFamilyOrFriend;
                        $scope.PreOpCallObj.IsLeftMsgWithFamilyOrFriend = editcase[0].IsLeftMsgWithFamilyOrFriend;
                        $scope.PreOpCallObj.IsLeftMsgWithPatient = editcase[0].IsLeftMsgWithPatient;
                        $scope.PreOpCallObj.IsNoResponse = editcase[0].IsNoResponse;
                        $scope.PreOpCallObj.IsArrivalTimeShared = editcase[0].IsArrivalTimeShared;
                        $scope.PreOpCallObj.IsAccompanyShared = editcase[0].IsAccompanyShared;

                        $scope.PreOpCallObj.IsDrinkPlentyWaterShared = editcase[0].IsDrinkPlentyWaterShared;
                        $scope.PreOpCallObj.IsNpoAfterMidnightShared = editcase[0].IsNpoAfterMidnightShared;
                        $scope.PreOpCallObj.IsTakeBpHeartMedShared = editcase[0].IsTakeBpHeartMedShared;
                        $scope.PreOpCallObj.IsDoNotTakeBpMedShared = editcase[0].IsDoNotTakeBpMedShared;
                        $scope.PreOpCallObj.IsNoMakeupJewelMoistShared = editcase[0].IsNoMakeupJewelMoistShared;

                        $scope.PreOpCallObj.IsCoPay = editcase[0].IsCoPay;
                        $scope.PreOpCallObj.DeleteInd = editcase[0].DeleteInd;
                        $scope.PreOpCallObj.CoPayNotes = editcase[0].CoPayNotes;
                        $scope.PreOpCallObj.DropsStartTime = editcase[0].DropsStartTime;
                        var StartTime = $filter("date")(editcase[0].ContactStartTime, "h:mm a");
                        $scope.PreOpCallObj.ContactStartTime = StartTime;

                    }
                }




                $scope.closeuib = function () {
                    $uibModalInstance.dismiss("cancel");
                    /*$uibModalInstance.close("close");*/
                };
                //$scope.SaveAlderetpopup = function () {
                //    $uibModalInstance.close($scope.PreOpCallObj);
                //}
                $scope.savePreOpcallpopup = function () {
                    if ($scope.PreOpCallObj.ContactType == "") {
                        alertify.error("Please select Contact Type!");
                        return;
                    }
                    if ($scope.PreOpCallObj.ContactStartDate == "") {
                        alertify.error("Please select Date!");
                        return;
                    }
                    if ($scope.PreOpCallObj.ContactStartTime == "") {
                        alertify.error("Please select Time!");
                        return;
                    }
                    eHnotePatientDataService.AddUpdatePatientPreOpCallDetails($scope.PreOpCallObj).then(function (resp) {
                        if (resp.data.Status == "Success") {
                            let Obj = {
                                "PatientId": $scope.cacheStorageItem.PatientID,
                                "AppointmentId": $scope.cacheStorageItem.AppointmentId,
                            }
                            eHnotePatientDataService.GetPatientPreOpCallDetailsList(Obj).then(function (resp) {
                                if (resp.data.status == "Success") {
                                    $scope.PreOpObj.PreOpCallDetails = resp.data.rows || [];
                                    $scope.PreOpObj.IsPreOpCallSummaryShow = true;
                                }
                                $uibModalInstance.close($scope.PreOpCallObj);

                            }, function (err) {

                            });

                        }
                    }, function () {

                    });
                };
            }
        });
        $scope.mInstanceAdd.result.then(function (data) {
        }, function (cancel) {

        });
    };
