    $scope.ClearAldreteScore = function (item) {

        angular.forEach(item.AldreteScoreDetailTypes, function (sitem) {
            //sitem.IsChecked = false;            
            sitem.DeleteInd = "Y";
        });
        item.Value = '';

        item.IsChecked = false;
        item.DeleteInd = "Y";
        let sum = 0;
        angular.forEach($scope.PreOpObj.AlderetScoreDetails, function (sitem) {
            if (sitem.IsChecked == true) {
                sum += sitem.Value;
            }
        });

        $scope.PreOpObj.TotalAlderetScore = sum;
    }
