    $scope.OnClickDiabetesOrVien = function (Type, Value) {
        if (Type == 'IsVein') {
            if (Value == 'Yes') {
                if ($scope.PreOpObj.IsVeinOpened == null || $scope.PreOpObj.IsVeinOpened == false) {
                    $scope.PreOpObj.IsVeinOpened = true;
                } else {
                    $scope.PreOpObj.IsVeinOpened = null;
                }
            } else {
                if ($scope.PreOpObj.IsVeinOpened == null || $scope.PreOpObj.IsVeinOpened == true) {
                    $scope.PreOpObj.IsVeinOpened = false;
                } else {
                    $scope.PreOpObj.IsVeinOpened = null;
                }

            }
        }
        if (Type == 'IsDiabetes') {
            var Diabeteslength = 0;
            if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                    item.DiabetesResult = item.DiabetesResult || '';
                    if (item.DiabetesResult != '' && item.DeleteInd == 'N') {
                        Diabeteslength++
                    }
                });
            }
            if (Value == 'Yes') {
                if (Diabeteslength !== 0) {
                    alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to Delete Diabetes?</h4>", function () {
                        $scope.PreOpObj.IsHypoglycemia = null;
                        $scope.PreOpObj.IsHypoglycemiaCheck = false;
                        $scope.PreOpObj.IsDiabetesNO = null;
                        if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                            angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                                item.DiabetesTimingId = item.DiabetesTimingId || 0;
                                var index = $scope.PreOpObj.DiabetesTimings.indexOf(item);
                                if (item.DiabetesTimingId != 0) {
                                    if (index > -1) {
                                        item.DeleteInd = 'Y';
                                    }
                                } else {
                                    if (index > -1) {
                                        $scope.PreOpObj.DiabetesTimings.splice(index, 1);
                                    }
                                }
                            });
                        }
                        if ($scope.PreOpObj.IsDiabetes == null || $scope.PreOpObj.IsDiabetes == false) {
                            $scope.PreOpObj.IsDiabetes = true;
                            let object = {
                                "DiabetesTimingId": 0,
                                "DiabetesResult": null,
                                "DiabetesTime": "",
                                "DeleteInd": 'N',
                                "DiabetesGivenBy": 0
                            };
                            $scope.PreOpObj.DiabetesTimings.push(object);

                        }
                        else {
                            $scope.PreOpObj.IsDiabetes = null;
                            $scope.PreOpObj.DiabetesResult = "";
                            $scope.PreOpObj.DiabetesTime = "";
                            if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                                angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                                    item.DiabetesTimingId = item.DiabetesTimingId || 0;
                                    var index = $scope.PreOpObj.DiabetesTimings.indexOf(item);
                                    if (item.DiabetesTimingId != 0) {
                                        if (index > -1) {
                                            item.DeleteInd = 'Y';
                                        }
                                    } else {
                                        if (index > -1) {
                                            $scope.PreOpObj.DiabetesTimings.splice(index, 1);
                                        }
                                    }
                                });
                            }
                        }
                        $scope.$digest();
                    }, function () {

                    });
                } else {
                    $scope.PreOpObj.IsDiabetes = true;
                    $scope.PreOpObj.IsHypoglycemiaCheck = false;
                    $scope.PreOpObj.DiabetesResult = "";
                    $scope.PreOpObj.DiabetesTime = "";
                    if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                        angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                            item.DiabetesTimingId = item.DiabetesTimingId || 0;
                            var index = $scope.PreOpObj.DiabetesTimings.indexOf(item);
                            if (item.DiabetesTimingId != 0) {
                                if (index > -1) {
                                    item.DeleteInd = 'Y';
                                }
                            } else {
                                if (index > -1) {
                                    $scope.PreOpObj.DiabetesTimings.splice(index, 1);
                                }
                            }
                        });
                    }
                    let object = {
                        "DiabetesTimingId": 0,
                        "DiabetesResult": null,
                        "DiabetesTime": "",
                        "DeleteInd": 'N',
                        "DiabetesGivenBy": 0
                    };
                    $scope.PreOpObj.DiabetesTimings.push(object);
                }


            } else {
                if (Diabeteslength !== 0) {
                    alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to Delete Diabetes?</h4>", function () {
                        if ($scope.PreOpObj.IsDiabetes == null || $scope.PreOpObj.IsDiabetes == true) {
                            $scope.PreOpObj.IsDiabetes = false;

                        } else {
                            $scope.PreOpObj.IsDiabetes = null;
                            $scope.PreOpObj.IsDiabetesNO = null;
                            $scope.PreOpObj.IsHypoglycemia = null;
                            $scope.PreOpObj.IsHypoglycemiaCheck = false;
                        }
                        $scope.PreOpObj.DiabetesResult = "";
                        $scope.PreOpObj.DiabetesTime = "";
                        if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                            angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                                item.DiabetesTimingId = item.DiabetesTimingId || 0;
                                var index = $scope.PreOpObj.DiabetesTimings.indexOf(item);
                                if (item.DiabetesTimingId != 0) {
                                    if (index > -1) {
                                        item.DeleteInd = 'Y';
                                    }
                                } else {
                                    if (index > -1) {
                                        $scope.PreOpObj.DiabetesTimings.splice(index, 1);
                                    }
                                }
                            });
                        }
                        $scope.$digest();
                    }, function () {

                    });
                } else {
                    $scope.PreOpObj.IsDiabetes = false;
                    $scope.PreOpObj.DiabetesResult = "";
                    $scope.PreOpObj.DiabetesTime = "";
                    $scope.PreOpObj.IsHypoglycemiaCheck = false;

                    if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                        angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                            item.DiabetesTimingId = item.DiabetesTimingId || 0;
                            var index = $scope.PreOpObj.DiabetesTimings.indexOf(item);
                            if (item.DiabetesTimingId != 0) {
                                if (index > -1) {
                                    item.DeleteInd = 'Y';
                                }
                            } else {
                                if (index > -1) {
                                    $scope.PreOpObj.DiabetesTimings.splice(index, 1);
                                }
                            }
                        });
                    }
                }


            }
        }
        if (Type == 'IsNasalcanula') {
            if (Value == 'Yes') {
                if ($scope.PreOpObj.IsNasalcanula == null || $scope.PreOpObj.IsNasalcanula == false) {
                    $scope.PreOpObj.IsNasalcanula = true;
                } else {
                    $scope.PreOpObj.IsNasalcanula = null;
                }
            } else {
                if ($scope.PreOpObj.IsNasalcanula == null || $scope.PreOpObj.IsNasalcanula == true) {
                    $scope.PreOpObj.IsNasalcanula = false;
                } else {
                    $scope.PreOpObj.IsNasalcanula = null;
                }

            }
        }
    };
    $scope.OnClickHypoglycemia = function () {

        if ($scope.PreOpObj.IsHypoglycemiaCheck == true) {
            $scope.PreOpObj.IsHypoglycemia = true;
            if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                    item.DiabetesTimingId = item.DiabetesTimingId || 0;
                    var index = $scope.PreOpObj.DiabetesTimings.indexOf(item);
                    if (item.DiabetesTimingId != 0) {
                        if (index > -1) {
                            item.DeleteInd = 'Y';
                        }
                    } else {
                        if (index > -1) {
                            $scope.PreOpObj.DiabetesTimings.splice(index, 1);
                        }
                    }
                });
            }
            if ($scope.PreOpObj.IsHypoglycemia == null || $scope.PreOpObj.IsHypoglycemia == true) {
                let object = {
                    "DiabetesTimingId": 0,
                    "DiabetesResult": null,
                    "DiabetesTime": "",
                    "DeleteInd": 'N',
                    "DiabetesGivenBy": 0
                };
                $scope.PreOpObj.DiabetesTimings.push(object);

            }
        }
        else {
            $scope.PreOpObj.IsHypoglycemia = false;
            if ($scope.PreOpObj.DiabetesTimings.length > 0) {
                angular.forEach($scope.PreOpObj.DiabetesTimings, function (item) {
                    item.DiabetesTimingId = item.DiabetesTimingId || 0;
                    var index = $scope.PreOpObj.DiabetesTimings.indexOf(item);
                    if (item.DiabetesTimingId != 0) {
                        if (index > -1) {
                            item.DeleteInd = 'Y';
                        }
                    } else {
                        if (index > -1) {
                            $scope.PreOpObj.DiabetesTimings.splice(index, 1);
                        }
                    }
                });
            }
        }
    }

