    function validateIVAccessBeforeSave() {
        const ivList = ($scope.PreOpObj.IVAccessDetailsList || []).filter(iv => iv.DeleteInd === 'N');
        if (ivList.length === 0) return true;

        function isIVCleared(iv) {
            const isMainEmpty =
                (iv.IVSite == null || iv.IVSite === '') &&
                (iv.PatencyStatus == null || iv.PatencyStatus === '') &&
                (iv.IVNeedleSize == null || iv.IVNeedleSize === '') &&
                (iv.IVFluidsId == null || iv.IVFluidsId === '') &&
                (iv.IVSiteFluids == null || iv.IVSiteFluids === '') &&
                (iv.NoOfAttempts == null || iv.NoOfAttempts === '') &&
                (iv.IvAccessGivenBy == null || iv.IvAccessGivenBy === '') &&
                (iv.IvAccessGivenByTime == null || iv.IvAccessGivenByTime === '') &&
                (iv.IVArm == null || iv.IVArm === '');

            const isConditionCleared = !(
                iv.ConditionList && iv.ConditionList.some(c => c.DeleteInd === 'N')
            );

            const isBlockedCleared = !(
                iv.IVBlockedArray && iv.IVBlockedArray.some(b => b.IsSelected === true)
            );

            return isMainEmpty && isConditionCleared && isBlockedCleared;
        }

        //  Find which IVs have data
        const ivDataStatus = ivList.map(iv => !isIVCleared(iv)); // true = has data, false = cleared

        //  If any later IV has data while earlier ones are cleared → collect them
        let clearedBeforeData = [];
        for (let i = 0; i < ivDataStatus.length; i++) {
            if (ivDataStatus[i]) {
                // current IV has data → check all before this
                for (let j = 0; j < i; j++) {
                    if (!ivDataStatus[j] && !clearedBeforeData.includes(j + 1)) {
                        clearedBeforeData.push(j + 1);
                    }
                }
            }
        }

        //  If found any earlier cleared IVs → show alert
        if (clearedBeforeData.length > 0) {
            const ivNames = clearedBeforeData.map(n => "IV" + n).join(", ");
            alertify.error(`Please complete ${ivNames} before saving.`);
            return false;
        }

        return true;
    }
