    $scope.DeleteGeneralOrder = function (Mitem, item,Type) {
        var index = Mitem.GeneralOrders.indexOf(item);
        if (item.GeneralOrderId === 0) {
            if (index > -1) {
                Mitem.GeneralOrders.splice(index, 1);
            }
        } else {
            item.DeleteInd = "Y";
        }
        $scope.PreopOrderinit('');
    }
