    $scope.MedicationOrdersReviwedByLogs = function (item) {
        $scope.LogObj.LogArray = [];
        item.UserType = item.UserType || '';
        if (item.ReviewedBy != null || item.ReviewedByPassword != '') {
            let givenByUser = '';
            var ReviewedByArraylist = $filter("filter")($scope.allUserList, function (eitem) { return eitem.DoctorID == item.ReviewedBy });
            if (ReviewedByArraylist.length > 0) {
                givenByUser = angular.copy(ReviewedByArraylist[0].SecondUserFullName) +
                    (ReviewedByArraylist[0].LicenseNumber ? " Lic:" + angular.copy(ReviewedByArraylist[0].LicenseNumber) : "");
            }
            let ActionDescription = ''
            if (item.MedTypeId == 2) {
                ActionDescription = `Surgeon Orders Reviewed By ${givenByUser} in Pre-Op ${item.UserType} For Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            } else if (item.MedTypeId == 1) {
                ActionDescription = `Anesthesia Orders Reviewed By ${givenByUser} in Pre-Op ${item.UserType} For Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            } else {
                ActionDescription = `Medication Orders Reviewed By ${givenByUser} in Pre-Op ${item.UserType} For Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            }

            let obj = {
                "LogId": 0,
                "ModuleId": 2,
                "ModuleName": "ASC",
                "SubModuleId": 9,
                "SubModuleName": "Pre-Op",
                "ScreenType": "Pre-Op Nurse",
                "ActionType": "Added",
                "OldActionDescription": '',
                "NewActionDescription": ActionDescription,
                //"ActionDescription": ActionDescription,
                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
            };
            $scope.LogObj.LogArray.push(obj);

            eHnoteSurgeryService.AddAuditLog($scope.LogObj).then(function (resp) {
                if (resp.data.status == "Success") {
                    console.log("Added");
                }
            })
        }
    };

