    $scope.findDifferencesArray = function (savedArray, editedArray) {
        var differences = [];
        
        angular.forEach(savedArray, function (item) {
            item.AscMultiCheckValueArray = item.AscMultiCheckValueArray || [];
            item.ChecklistDate = item.ChecklistDate || null;
            item.Remarks = item.Remarks || '';
            item.DeleteInd = item.DeleteInd || 'N';
            var SavedData = [];
            
            if (item.AscMultiCheckValueArray.length > 0) {
                SavedData = $filter("filter")(item.AscMultiCheckValueArray, { "DeleteInd": "N" }, true);
            }
            var edited = editedArray.filter(function (eitem) {

                var EditedData = [];

                eitem.AscMultiCheckValueArray = eitem.AscMultiCheckValueArray || [];
                eitem.ChecklistDate = eitem.ChecklistDate || null;
                eitem.Remarks = eitem.Remarks || '';
                eitem.DeleteInd = eitem.DeleteInd || 'N';

                if (eitem.AscMultiCheckValueArray.length > 0) {
                    EditedData = $filter("filter")(eitem.AscMultiCheckValueArray, { "DeleteInd": "N" }, true);
                }

                return ((eitem.CheckListCategoryId == item.CheckListCategoryId) && (item.CheckListId == eitem.CheckListId) && (item.Value == eitem.Value) && (item.Remarks == eitem.Remarks) && (item.ChecklistDate == eitem.ChecklistDate) && (item.DeleteInd == eitem.DeleteInd) && (SavedData.length == EditedData.length));
            }) || [];


            if (edited.length == 0) {
                differences.push(item);
             }

        });

        return differences;
    };



