    $scope.GetReactionNames = function (item) {

        if (!item.Reactions || !item.Reactions.length) {
            return '';
        }

        return item.Reactions
            .filter(function (r) {
                return r.DeleteInd !== 'Y';
            })
            .map(function (r) {
                return r.ReactionName;
            })
            .join(', ');
    };

    $scope.GetReactionIds = function (item) {

        if (!item.Reactions || !item.Reactions.length) {
            return '';
        }

        return item.Reactions
            .filter(function (r) {
                return r.DeleteInd !== 'Y';
            })
            .map(function (r) {
                return r.ReactionId;
            })
            .sort()
            .join(',');
    };


    $scope.compareAllergyItems = function () {
        $scope.PreOpObj.AllergyItems = $scope.PreOpObj.AllergyItems || [];
        $scope.LogObj.AllergyItems = $scope.LogObj.AllergyItems || [];
        let count = 0;
        let allergyNames = '';
        let dltcount = 0;
        let DifferenceItem = [];
        let GivenByUser = '';

        var ReviewedByArraylist = $filter("filter")($scope.allUserList, function (eitem) { return eitem.DoctorID == $scope.UserId });
        if (ReviewedByArraylist.length > 0) {
            GivenByUser = angular.copy(ReviewedByArraylist[0].SecondUserFullName) +
                (ReviewedByArraylist[0].LicenseNumber ? " Lic:" + angular.copy(ReviewedByArraylist[0].LicenseNumber) : "");
        }

        let dltallergyNames = '';
        angular.forEach($scope.PreOpObj.AllergyItems, function (item) {
            item.DurationDate = $filter('date')(item.DurationDate, "MM-dd-yyyy") || null;
            item.DurationType = item.DurationType || '';
            item.Duration = item.Duration || '';
            item.Remarks = item.Remarks || '';
            if (item.DeleteInd == 'Y') {
                if (dltcount > 0) {
                    dltallergyNames += ', ';
                }
                dltallergyNames += item.AllergyName;
                dltcount++;
            } else {
                var edited = $scope.LogObj.AllergyItems.filter(function (eitem) {
                    eitem.DurationDate = $filter('date')(eitem.DurationDate, "MM-dd-yyyy") || null;
                    eitem.DurationType = eitem.DurationType || '';
                    eitem.Duration = eitem.Duration || '';
                    eitem.Remarks = eitem.Remarks || '';
                    return ((eitem.AllergyId == item.AllergyId) && ($scope.GetReactionIds(eitem) == $scope.GetReactionIds(item)) && (eitem.StatusId == item.StatusId) && (eitem.DurationDate == item.DurationDate) && (eitem.SeverityId == item.SeverityId) && (eitem.Duration == item.Duration) && (eitem.AllergyTypeId == item.AllergyTypeId) && (eitem.Remarks == item.Remarks));
                }) || [];


                if (edited.length == 0) {
                    if (count > 0) {
                        allergyNames += ', ';
                    }
                    allergyNames += item.AllergyName;
                    count++;
                    DifferenceItem.push(item);
                }
            }

        });

        if (count != 0) {
            let description = '';
            //if (count === 1) {
            //    description = `Allergy - ${allergyNames.toUpperCase()} In Pre-Op(Anesthesia) for Appointment ID: ${GivenByUser}`;
            //} else {
            //    description = `Allergies - ${allergyNames.toUpperCase()} In Pre-Op(Anesthesia) for Appointment ID: ${GivenByUserd}`;
            //}
            var Affecteditem = '';
            var OldAffecteditem = '';
            angular.forEach(DifferenceItem, function (itemA) {
                var reactionNames = $scope.GetReactionNames(itemA);

                Affecteditem += `\nAllergy - ${itemA.AllergyName.toUpperCase()}` +
                    (reactionNames ? `, Reactions: ${reactionNames}` : '') +
                    (itemA.SeverityName ? `, Severity: ${itemA.SeverityName}` : '') +
                    `, Status: ${itemA.StatusName}` +
                    `, In Pre-Op(Nurse)` +
                    `, By User: ${GivenByUser}`;
                //Affecteditem += `\nAllergy - ${itemA.AllergyName.toUpperCase()}, Severity: ${itemA.SeverityName}, Status: ${itemA.StatusName}, In Pre-Op(Anesthesia), By User: ${GivenByUser}`;

                angular.forEach($scope.LogObj.AllergyItems, function (itemB) {
                    if (itemA.AllergyId === itemB.AllergyId) {
                        var oldReactionNames = $scope.GetReactionNames(itemB);

                        OldAffecteditem += `\nAllergy - ${itemB.AllergyName.toUpperCase()}` +
                            (oldReactionNames ? `, Reactions: ${oldReactionNames}` : '') +
                            (itemB.SeverityName ? `, Severity: ${itemB.SeverityName}` : '') +
                            `, Status: ${itemB.StatusName}` +
                            `, In Pre-Op(Nurse)` +
                            `, By User: ${GivenByUser}`;
                        //OldAffecteditem += `\nAllergy - ${itemB.AllergyName.toUpperCase()}, Severity: ${itemB.SeverityName}, Status: ${itemB.StatusName}, In Pre-Op(Anesthesia), By User: ${GivenByUser}`;
                    }
                });
            });

            let obj = {
                "LogId": 0,
                "ModuleId": 2,
                "ModuleName": "ASC",
                "SubModuleId": 9,
                "SubModuleName": "Pre-Op",
                "ScreenType": "Pre-Op Nurse",
                "ActionType": "Edited",
                "OldActionDescription": OldAffecteditem,
                "NewActionDescription": Affecteditem,
                //"ActionDescription": description,
                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
            };
            $scope.LogObj.LogArray.push(obj);
        }

        if (dltcount != 0) {
            let description = '';
            if (dltcount === 1) {
                description = `Allergy - ${dltallergyNames.toUpperCase()} In Pre-Op(Nurse) for User: ${GivenByUser}`;
            } else {
                description = `Allergies - ${dltallergyNames.toUpperCase()} In Pre-Op(Nurse) for User: ${GivenByUser}`;
            }
            let obj = {
                "LogId": 0,
                "ModuleId": 2,
                "ModuleName": "ASC",
                "SubModuleId": 9,
                "SubModuleName": "Pre-Op",
                "ScreenType": "Pre-Op Nurse",
                "ActionType": "Deleted",
                "OldActionDescription": description,
                "NewActionDescription": '',
                //"ActionDescription": description,
                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
            };
            $scope.LogObj.LogArray.push(obj);
        }

    }


